 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append(comp)
    # The largest unoccupied cavity is color 8; a 2-cell cavity is color 7.
    # Keep all other background unchanged.
    if components:
        largest = max(components, key=len)
        if len(largest) > 1:
            for r, c in largest:
                out[r][c] = 8
    for comp in components:
        if len(comp) == 2:
            for r, c in comp:
                out[r][c] = 7
    return out
