 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            components.append(comp)
    if components:
        # Recolor the largest zero component 8 and the smallest one 7.
        largest = max(components, key=len)
        smallest = min(components, key=len)
        for r, c in largest:
            out[r][c] = 8
        for r, c in smallest:
            out[r][c] = 7
    return out
