            while q:
                y,x=q.pop();co.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==0 and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            cs.append(co)
    if cs:
        # The largest compact background region gets 8; the special 7 region
        # is a fully filled rectangle of at most four cells in the upper half.
        for y,x in max(cs,key=len): out[y][x]=8
        rect=[]
        for co in cs:
            y0,y1=min(y for y,x in co),max(y for y,x in co)
            x0,x1=min(x for y,x in co),max(x for y,x in co)
            if len(co)<=4 and len(co)==(y1-y0+1)*(x1-x0+1) and y0<h//2:
                rect.append(co)
        if rect:
