        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            comps.append(comp)
    if comps:
        # Select the connected background patch farthest to the right as 8.
        right_patch = max(comps, key=lambda comp: sum(x for y, x in comp) / len(comp))
